('كود خصم 2B 2026 تخفيض حتي 50% علي كل الطلبيات', 'CC11', 'استخدم كود خصم 2B 2026 جديد (CC11) عند الشراء للاستفادة من تخفيض حتي 50% علي كل المنتجات من توبي مصر، رمز الكوبون (CC11) يمنحك 10% خصم اضافي علي طلبيتك.', 1, '%50 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 1, 5, 'https://2b.com', 163, 98, NOW(), NOW()),
('كود خصم توبي مصر بقيمة 20% فعال علي كافة الالكترونيات', 'CC12', 'تستطيع تفعيل كوبون خصم 2B 2026 (CC12) الجديد علي كل المنتجات للاستفادة من 5% خصم ثابت علي كل الطلبيات، رمز الكوبون (CC12) يعمل علي كافة اقسام المتجر والتطبيق.', 1, '%5 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 0, 5, 'https://2b.com', 76, 98, NOW(), NOW()),
('كود خصم تو بي اول طلب بقيمة 20% تخفيض حتي 2000 جنيه', '2NAVA', 'احصل علي كود خصم تو بي اول طلب (2NAVA) والصقه في صفحة الدفع للاستفادة من 20% خصم مباشر علي كل الطلبيات تخفيض حد اقصي 2000 جنيه لجميع العملاء.', 1, '%18 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 0, 5, 'https://2b.com', 132, 98, NOW(), NOW()),
('كود خصم تو بي مصر (CC13) بقيمة 10% علي الموبايلات والتابلت من موقع 2B', 'CC13', 'كود خصم تو بي مصر (CC13) يعمل علي كل الموبايلات والتابلت المتوفرة علي المتجر بقيمة 10% عند اتمام الدفع، فعل كوبون خصم 2B (CC13) واحصل علي 5% خصم اضافي علي طلبيتك.', 1, '%10 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 1, 5, 'https://2b.com', 419, 98, NOW(), NOW()),
('كود خصم 6 ستريت 2026 بقيمة حتي 25% فعال للمستخدمين الجدد', 'DC14', 'استخدم كود خصم 6 ستريت 2026 (DC14) عند الشراء للاستفادة من تخفيض بقيمة 25% علي جميع طلبات المستخدمين الجدد، كما يمنحك كوبون خصم 6 ستريت (DC14) تخفيضات اضافية بقيمة 10% فعال علي كل المشتريات.', 2, '%25 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 0, 5, 'https://en-sa.6thstreet.com', 182, 98, NOW(), NOW()),
('كود خصم 6th street السعودية بقيمة حتي 10% علي كل شئ', 'MATH', 'قم بتفعيل كود خصم 6th street السعودية (MATH) لتحصل علي تخفيضات مذهلة بقيمة حتي 10% علي كل شئ، استخدام كوبون خصم 6 ستريت (MATH) لتحصل علي اقوي العروض من المتجر اون لاين.', 2, '%10 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 0, 5, 'https://en-sa.6thstreet.com', 352, 98, NOW(), NOW()),
('كود خصم 6 ستريت 2026 تخفيض حتي 12% للمستخدمين الحاليين', 'DC13', 'يمكنك الان تفعيل كود خصم 6 ستريت 2026 (DC13) للحصول علي تنزيلات تصل الي 12% علي طلبات العملاء الحاليين، استخدم الان كود خصم 6th street الجديد (DC13) واحصل علي تخفيض حتي 5% للعملاء الجدد علي التطبيق.', 2, '%12 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 1, 5, 'https://en-sa.6thstreet.com', 69, 98, NOW(), NOW()),
('كوبون خصم 6 ستريت بقيمة 25% فعال علي طلبات العملاء الجدد', 'AB3', 'فعل الان كوبون خصم 6 ستريت (AB3) لتتمكن من توفير حتي 25% من قيمة منتجاتك اذا كنت احد العملاء الجدد، كود خصم 6th street (AB3) يشمل كافة المنتجات المخفضة والغير مخفضة من المتجر. كود خصم 6 ستريت', 2, '%25 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 0, 5, 'https://en-sa.6thstreet.com', 449, 98, NOW(), NOW()),
('كود خصم 6th street بقيمة 12% علي اول طلب للعملاء الحاليين', 'AB33', 'كود خصم 6th street الجديد (AB33) يمكنك من الحصول علي تخفيض بقيمة تصل الي 12% فعال علي اول طلب شراء للعملاء الحاليين، كود خصم 6 ستريت 2026 (AB33) يمنحك تخفيضات وعروض اضافية علي كل عملية شراء اون لاين. كود خصم 6th street', 2, '%12 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 0, 5, 'https://en-sa.6thstreet.com', 361, 98, NOW(), NOW()),
('كود خصم 6 ستريت السعودية بقيمة 16% فعال للعميل الجديد', 'SSA67', 'اشتري الان الاحذية والحقائب الراقية وفعلي كود خصم 6 ستريت السعودية (SSA67) لتستفيدي من تخفيض بقيمة تصل الي 16% علي عربة الشراء الخاصة بك من موقع 6thstreet مقدم للعميل الجديد.', 2, '%16 خصم', 'discount_code', '2026-12-31', NULL, 'published', 1, 1, 1, 5, 'https://en-sa.6thstreet.com', 57, 98, NOW(), NOW()),
('كود خصم 6 ستريت اول طلب بقيمة 11% علي طلبات العميل القديم', 'SSA68', 'يمكنك تطبيق كود خصم 6 ستريت اول طلب (SSA68) علي مشترياتك الان للاستفادة من تنزيلات حتي 11% خصم فوري للعميل القديم علي المتجر، كود خصم 6th street هذا (SSA68) يشمل كل اقسام المتجر والمنتجات. كود خصم 6th street 30', 2, '%11 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 0, 5, 'https://en-sa.6thstreet.com', 431, 98, NOW(), NOW()),
('كوبون خصم 6th street تخفيض بقيمة 16% للعملاء الجدد', 'SSA66', 'يعمل كوبون خصم 6th street (SSA66) علي كل المنتجات من المتجر بقيمة حتي 16% خصم مباشر عند الدفع للعملاء الجدد. كما يمنحك كود خصم 6 ستريت (SSA66) تخفيض 10% اضافي + شحن مجاني علي كل الطلبيات. كود خصم 6th street اول طلب', 2, '%16 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 0, 5, 'https://en-sa.6thstreet.com', 85, 98, NOW(), NOW()),
('كود خصم italist 2026 بقيمة 50% فعال علي كل المتجر', 'SH1', 'يمكنك تفعيل كوبون خصم italist (SH1) علي سلة مشترياتك عند شراء الملابس من التشكيلة الجديدة وسوف تحصل علي تخفي حتي 45% فعال علي كافة الطلبيات من ايطالست.', 3, '%45 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 1, 5, 'https://italist.com', 143, 98, NOW(), NOW()),
