('كود خصم موقع اديداس بقيمة 25% علي كل المشتريات', 'RAN252', 'يمنحك كود خصم موقع اديداس (RAN252) تخفيض حتي 25% علي كافة مشترياتك من موقع adidas اون لاين. كما يمكنك الحصول علي الاحذية والملابس الرياضية بخصم اضافي 10% عند تنشيط كوبون خصم اديداس (RAN252) الفعال للعملاء الجدد.', 6, '%25 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 0, 5, 'https://adidas.com', 246, 98, NOW(), NOW()),
('كود خصم اسواق التميمي اول طلب بقيمة 15% علي كل الطلبيات', 'D4', 'فعل كوبون خصم اسواق التميمي (D4) عند شراء المنتجات المختلفة من المتجر للاستفادة من 10% خصم مباشر علي كل طلبياتك من tamimi markets.', 7, '%10 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 0, 5, 'https://tamimimarkets.com', 228, 98, NOW(), NOW()),
('كود خصم اوبتيك للعدسات الاصقة تنزيلات حتي 15% علي اول طلب', 'RAM', 'استخدم الان كود خصم اوبتيك 2026 (RAM) واستفد من تنزيلات بقيمة حتي 10% فعال لجميع العملاء علي كل النظارات، كما يوفر لك كوبون خصم اوبتيك (RAM) اقوي العروض الاضافية للعملاء الجدد عند القيام باول طلب.', 8, '%10 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 1, 5, 'https://optique.sa', 127, 98, NOW(), NOW()),
('كوبون خصم elegantie جديد وفعال 100% علي اول طلب', 'EL20', 'سارع الان في تطبيق كود خصم إليخانسي 2026 واحصل علي جميع منتجات العناية بالبشرة والشعر بخصم يصل الي 10% علي جميع الطلبات اون لاين من المتجر.', 9, '%10 خصم', 'discount_code', '2026-12-31', NULL, 'published', 0, 1, 0, 5, 'https://elegantie.market', 91, 98, NOW(), NOW()),
