-- ========================================================
-- AQWACODE SAFE PRODUCTION DATA IMPORT SQL
-- Compatible with Hostinger MySQL and utf8mb4
-- NO DROP TABLE / NO TRUNCATE TABLE (Preserves existing data)
-- Contains 618 Stores and 1127 Coupons
-- ========================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Categories

-- 2. Stores (618 stores)

-- 3. Coupons (1127 coupons)



SET FOREIGN_KEY_CHECKS = 1;

-- ========================================================
-- 4. MANDATORY VERIFICATION SQL QUERIES
-- Run these queries after import to verify table counts
-- ========================================================
SELECT 'Categories Count' AS metric, COUNT(*) AS count FROM `Category`
UNION ALL
SELECT 'Stores Count', COUNT(*) FROM `Store`
UNION ALL
SELECT 'Coupons Count', COUNT(*) FROM `Coupon`
UNION ALL
SELECT 'Published Stores', COUNT(*) FROM `Store` WHERE `status` = 'published'
UNION ALL
SELECT 'Active Coupons', COUNT(*) FROM `Coupon` WHERE `status` = 'published'
UNION ALL
SELECT 'Expired Coupons', COUNT(*) FROM `Coupon` WHERE `status` = 'expired';
